const passMark = 40;

function average(marks) {
  if (marks.length === 0) return 0;
  return marks.reduce((sum, m) => sum + m, 0) / marks.length;
}

function isPassing(mark) {
  return mark >= passMark;
}

module.exports = { average, isPassing, passMark };
